function solve(input) {
  const prices = input.trim().split(" ").map(Number);
  let min = Infinity, maxP = 0;
  for (let p of prices) {
    if (p < min) min = p;
    else if (p - min > maxP) maxP = p - min;
  }
  return maxP.toString();
}

