function solve(input) {
  const s = input.trim();
  const set = new Set();
  let l = 0, max = 0;
  for (let r = 0; r < s.length; r++) {
    while (set.has(s[r])) { set.delete(s[l]); l++; }
    set.add(s[r]);
    max = Math.max(max, r - l + 1);
  }
  return max.toString();
}

